def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    positive_years = sum(1 for value in values if value > 0)
    return {
        "value": positive_years,
        "trace": {
            "positive_years": positive_years,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years"
            }
        }
    }
